<a class="back" href="/dashboard">← Dashboard</a><div class="actions" style="justify-content:space-between"><h1>Customers</h1><a class="btn" href="/customers/new">Add customer</a></div><table><tr><th>Name</th><th>Email</th><th>Phone</th><th>Actions</th></tr><?php foreach($customers as $c): ?><tr><td><?= esc($c['full_name']) ?></td><td><?= esc($c['email']) ?></td><td><?= esc($c['phone']) ?></td><td class="actions"><a class="btn secondary" href="/customers/<?= $c['id'] ?>/edit">Edit</a><form method="post" action="/customers/<?= $c['id'] ?>" onsubmit="return confirm('Delete this customer?')" style="padding:0;border:0;box-shadow:none"><?= csrf_field() ?><input type="hidden" name="_method" value="DELETE"><button class="btn danger">Delete</button></form></td></tr><?php endforeach ?></table>
